import { Order } from './types';

export interface OrderPosition { createdAt: string; id: string }

function compareKey(aCreatedAt: string, aId: string, bCreatedAt: string, bId: string): number {
  if (aCreatedAt < bCreatedAt) return -1;
  if (aCreatedAt > bCreatedAt) return 1;
  if (aId < bId) return -1;
  if (aId > bId) return 1;
  return 0;
}

export class OrderRepository {
  constructor(private readonly rows: Order[]) {}

  /**
   * Returns the tenant's orders sorted ascending by (createdAt, id).
   * When `after` is given, only orders strictly after that pair are returned;
   * the pair need not correspond to an existing row. Tenant filtering is
   * applied before the position filter. The input array and rows are not mutated.
   */
  list(tenant: string, after?: OrderPosition): Order[] {
    return this.rows
      .filter(row => row.tenant === tenant)
      .filter(row => !after || compareKey(row.createdAt, row.id, after.createdAt, after.id) > 0)
      .sort((a, b) => compareKey(a.createdAt, a.id, b.createdAt, b.id));
  }
}
