{
  const rows = [
    { id: 'b', tenant: 't', createdAt: '2026-01-01', total: 2 },
    { id: 'c', tenant: 't', createdAt: '2026-01-01', total: 3 },
    { id: 'a', tenant: 't', createdAt: '2026-01-01', total: 1 },
    { id: 'z', tenant: 'o', createdAt: '2026-01-01', total: 9 },
    { id: 'd', tenant: 't', createdAt: '2026-01-02', total: 4 },
    { id: 'zz', tenant: 'o', createdAt: '2026-01-03', total: 9 }
  ];
  const snapshot = JSON.stringify(rows);
  const h = new OrderHandler(new OrderRepository(rows));
  // Walk all pages with equal dates: no repeats, no skips.
  const seen = [];
  let cursor;
  let pages = 0;
  do {
    const page = h.list(cursor === undefined ? { tenant: 't', limit: 2 } : { tenant: 't', limit: 2, cursor });
    seen.push(...page.items.map(x => x.id));
    cursor = page.nextCursor;
    pages++;
  } while (cursor !== null);
  assert.deepEqual(seen, ['a', 'b', 'c', 'd']);
  assert.equal(pages, 2);
  // Exact fit: no further item => null.
  assert.equal(h.list({ tenant: 't', limit: 4 }).nextCursor, null);
  assert.equal(h.list({ tenant: 't', limit: 3 }).nextCursor, '2026-01-01|c');
  // Cursor for a deleted row resumes strictly after the pair.
  assert.deepEqual(h.list({ tenant: 't', limit: 10, cursor: '2026-01-01|bb' }).items.map(x => x.id), ['c', 'd']);
  // Cursor pair of another tenant: filtering precedes pagination.
  const p = h.list({ tenant: 't', limit: 10, cursor: '2026-01-01|z' });
  assert.deepEqual(p.items.map(x => x.id), ['d']);
  assert.equal(p.nextCursor, null);
  // Other tenant's rows after the last tenant row don't produce a cursor.
  assert.equal(h.list({ tenant: 't', limit: 1, cursor: '2026-01-01|c' }).nextCursor, null);
  // Invalid requests.
  for (const bad of ['', '|', 'a|', '|a', 'a', 'a|b|c']) {
    assert.throws(() => h.list({ tenant: 't', limit: 1, cursor: bad }), /invalid request/);
  }
  for (const limit of [0, 101, 1.5, NaN, '5']) {
    assert.throws(() => h.list({ tenant: 't', limit }), /invalid request/);
  }
  assert.throws(() => h.list({ tenant: '', limit: 1 }), /invalid request/);
  assert.equal(h.list({ tenant: 't', limit: 100 }).items.length, 4);
  // No mutation of input array or rows.
  assert.equal(JSON.stringify(rows), snapshot);
}
console.log('public checks passed');
